const payloads=$('Descobrir projetos documentáveis').first().json.payloads??[];
const published=new Set($input.all()
  .map(item=>item.json??{})
  .filter(item=>item.type==='dir'&&String(item.path??'').startsWith('projects/'))
  .map(item=>String(item.name??'').trim().toLowerCase())
  .filter(Boolean));
const projects=payloads
  .filter(item=>item?.kind==='project'&&item?.projectSlug)
  .map(item=>({projectSlug:String(item.projectSlug),title:String(item.title??item.projectSlug)}))
  .sort((a,b)=>a.projectSlug.localeCompare(b.projectSlug));
if(projects.length===0) throw new Error('Nenhum projeto documentável foi encontrado pelas tags configuradas.');
return [{json:{
  availableProjects:projects.map(item=>item.projectSlug),
  publishedProjects:projects.filter(item=>published.has(item.projectSlug.toLowerCase())).map(item=>item.projectSlug),
  formDefinition:[{
    fieldLabel:'Projeto',
    fieldType:'dropdown',
    fieldOptions:{values:projects.map(item=>({option:item.projectSlug}))},
    requiredField:true
  },{
    fieldLabel:'Página raiz do Notion',
    fieldType:'text',
    placeholder:'https://www.notion.so/...',
    requiredField:false
  }]
}}];

const projectSlug=String($json.projectSlug??$json.Projeto??'').trim().toLowerCase();
const notionRootUrl=String($json.notionRootUrl??$json['Página raiz do Notion']??'').trim();
const notionValue=notionRootUrl.toLowerCase();
const selection=$('Preparar projetos para seleção').first().json;
const available=selection.availableProjects??[];
const published=selection.publishedProjects??[];
if(!available.includes(projectSlug)) throw new Error('Projeto inválido ou não disponível: '+projectSlug);
const isNotionUrl=notionValue.startsWith('https://www.notion.so/')||notionValue.startsWith('https://notion.so/')||notionValue.startsWith('https://www.notion.site/')||notionValue.startsWith('https://notion.site/');
const isPageId=/[0-9a-f]{32}|[0-9a-f-]{36}/i.test(notionRootUrl);
if(notionRootUrl&&!isNotionUrl&&!isPageId){
  throw new Error('Página raiz do Notion inválida. Informe uma URL notion.so/notion.site ou um page ID.');
}
const alreadyPublished=published.includes(projectSlug);
const cfg=$('Configuração do formulário').first().json;
return [{json:{
  projectSlug,
  notionRootUrl,
  documentationLayout:'separated',
  aiMode:'bootstrap',
  owner:cfg.owner,
  repository:cfg.repository,
  branch:cfg.branch,
  forceBootstrap:alreadyPublished,
  documentationMode:'bootstrap'
}}];
